UPDATE rag_outbox
SET lease_until = #{leaseUntil}, heartbeat_at = #{now}, row_version = row_version + 1
WHERE tenant_id = #{tenantId} AND event_id = #{eventId}
  AND status = 'publishing' AND lease_owner = #{leaseOwner}
  AND fencing_token = #{fencingToken} AND lease_until > #{now} AND deleted = 0
